using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using AICad.Contracts;
using AICad.Geometry;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Runtime;
using Newtonsoft.Json.Linq;
using JsonUtil=AICad.Contracts.Json;
[assembly:CommandClass(typeof(AICad.Bridge.DraftingNativeTests))]
namespace AICad.Bridge;
public sealed class DraftingNativeTests {
 [CommandMethod("AICADDRAFTINGTEST",CommandFlags.Modal|CommandFlags.NoUndoMarker)]public void Run(){string root=Environment.GetEnvironmentVariable("AICAD_TEST_ROOT")??"";if(!Path.IsPathRooted(root)||!File.Exists(Path.Combine(root,".aicad-test-root")))throw new InvalidOperationException("Isolated root required.");var cases=new List<object>();int failed=0;void Test(string name,Action run){try{run();cases.Add(new{name,passed=true});}catch(System.Exception e){failed++;cases.Add(new{name,passed=false,error=e.ToString()});}}
 var a=JsonUtil.Read<LibraryAnalysis>(File.ReadAllText(Path.Combine(root,"analysis.json")));var row=a.Blocks.Single(b=>b.Name=="QA_GC_KT_MBCUA");var layer=a.Layers.Single(l=>l.Name=="QA_KT_Cua");var asset=new BlockAsset{Id="DOOR",NativeSource=new(){FileHash=a.SourceHash,BlockName=row.Name,Min=row.Min,Max=row.Max,DynamicProperties=row.DynamicProperties.Where(p=>!p.ReadOnly).ToList()},Usage=new(){Role="door",Layer=layer.Name,WidthParameter="KT CUA",ThicknessParameter="KHUÔN",ConversionConfirmed=true,Reviewed=true,Values=new(){["CUA"]="D01_MB_Cua di 1 canh_Line"}}};var t=new TemplateProfile{Id="DRAFT_TEST",Version="1.0.0",Blocks=new(){asset},Layers=new(){new(){Name=layer.Name,Color=layer.Color,Appearance=new(){LineType=layer.LineType,LineWeight=layer.LineWeight,Rgb=layer.Rgb,Plottable=layer.Plottable,SourceHash=a.SourceHash}}}};
 DrawingPlan Plan(Operation op)=>new(){Template=t,TemplateHash=JsonUtil.Hash(t),Scope=Validation.Box(-100000,-100000,100000,100000).ToList(),Operations=new(){op}};
 foreach(int width in new[]{900,1100,1500})Test("Real dynamic door parameter "+width+" at scale 1 and original layer",()=>{using var db=new Database(true,true);var old=HostApplicationServices.WorkingDatabase;try{HostApplicationServices.WorkingDatabase=db;using var tx=db.TransactionManager.StartTransaction();var plan=Plan(new(){Kind="insert_block",AssetId="DOOR",Layer=layer.Name,OpeningWidth=width,WallThickness=220,Points=new(){new(0,0)}});var entities=EntityFactory.WritePlan(plan,db,tx);var b=(BlockReference)entities.Single();var props=b.DynamicBlockReferencePropertyCollection.Cast<DynamicBlockReferenceProperty>();if(Convert.ToDouble(props.Single(p=>p.PropertyName=="KT CUA").Value)!=width||b.ScaleFactors.X!=1||b.Layer!=layer.Name)throw new System.Exception("Parameter/layer/scale mismatch.");var definition=(BlockTableRecord)tx.GetObject(b.BlockTableRecord,OpenMode.ForRead);foreach(ObjectId id in definition)if(tx.GetObject(id,OpenMode.ForRead) is Entity e&&e.Layer.Contains("$"))throw new System.Exception("Mangled internal layer "+e.Layer);tx.Commit();}finally{HostApplicationServices.WorkingDatabase=old;}});
 Test("Visibility changes on the same native dynamic definition",()=>{using var db=new Database(true,true);var old=HostApplicationServices.WorkingDatabase;try{HostApplicationServices.WorkingDatabase=db;using var tx=db.TransactionManager.StartTransaction();var p=Plan(new(){Kind="insert_block",AssetId="DOOR",Layer=layer.Name,DynamicJson="{\"CUA\":\"D02_MB_Cua di 2 canh_Circle\"}",Points=new(){new(0,0)}});var b=(BlockReference)EntityFactory.WritePlan(p,db,tx).Single();if(Convert.ToString(b.DynamicBlockReferencePropertyCollection.Cast<DynamicBlockReferenceProperty>().Single(x=>x.PropertyName=="CUA").Value)!="D02_MB_Cua di 2 canh_Circle")throw new System.Exception("Visibility differs.");tx.Commit();}finally{HostApplicationServices.WorkingDatabase=old;}});
 Test("Existing layer conflict is rejected without recoloring",()=>{using var db=new Database(true,true);using var tx=db.TransactionManager.StartTransaction();var lt=(LayerTable)tx.GetObject(db.LayerTableId,OpenMode.ForWrite);var l=new LayerTableRecord{Name=layer.Name,Color=Autodesk.AutoCAD.Colors.Color.FromColorIndex(Autodesk.AutoCAD.Colors.ColorMethod.ByAci,1)};lt.Add(l);tx.AddNewlyCreatedDBObject(l,true);try{EntityFactory.Resources(Plan(new()),db,tx);throw new System.Exception("Conflict accepted.");}catch(CadException e)when(e.Code=="LAYER_CONFLICT"){}if(l.Color.ColorIndex!=1)throw new System.Exception("Layer recolored.");});
 Test("Native wall extents retain exact 220 and 110 thickness",()=>{foreach(int width in new[]{220,110})using(var e=EntityFactory.Primitive(new(){Kind="draw_wall",Height=width,Points=new(){new(0,0),new(3000,0)}})){var bounds=e.GeometricExtents;if(Math.Abs(bounds.MaxPoint.Y-bounds.MinPoint.Y-width)>1e-6)throw new System.Exception("Wall width differs.");}});
 Test("Actual stretched extents outside scope roll back",()=>{using var db=new Database(true,true);db.DisableUndoRecording(false);var old=HostApplicationServices.WorkingDatabase;try{HostApplicationServices.WorkingDatabase=db;try{using var tx=db.TransactionManager.StartTransaction();var p=Plan(new(){Kind="insert_block",AssetId="DOOR",Layer=layer.Name,OpeningWidth=1500,Points=new(){new(0,0)}});p.Scope=Validation.Box(-500,-500,1200,1200).ToList();EntityFactory.WritePlan(p,db,tx);tx.Commit();throw new System.Exception("Stretched bounds accepted.");}catch(CadException e)when(e.Code=="OUTSIDE_SCOPE"){}using var check=db.TransactionManager.StartOpenCloseTransaction();var bt=(BlockTable)check.GetObject(db.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)check.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);if(ms.Cast<ObjectId>().Any(id=>!id.IsErased))throw new System.Exception("Rollback left entities: "+string.Join(";",ms.Cast<ObjectId>().Where(id=>!id.IsErased).Select(id=>id.Handle+":"+check.GetObject(id,OpenMode.ForRead).GetType().Name)));}finally{HostApplicationServices.WorkingDatabase=old;}});
 Test("All 63 original layer appearances and CENTER pattern load natively",()=>{using var db=new Database(true,true);using var tx=db.TransactionManager.StartTransaction();var full=JsonUtil.Read<TemplateProfile>(JsonUtil.Write(t));full.Layers=a.Layers.Where(l=>l.Supported).Select(l=>new LayerAsset{Name=l.Name,Color=l.Color,Appearance=new(){LineType=l.LineType,LineWeight=l.LineWeight,Rgb=l.Rgb,Plottable=l.Plottable,SourceHash=a.SourceHash,Dashes=l.Dashes,PatternLength=l.PatternLength}}).ToList();EntityFactory.Resources(new DrawingPlan{Template=full},db,tx);var table=(LayerTable)tx.GetObject(db.LayerTableId,OpenMode.ForRead);foreach(var l in full.Layers){var native=(LayerTableRecord)tx.GetObject(table[l.Name],OpenMode.ForRead);if(native.Color.ColorIndex!=l.Color||native.LineWeight!=(LineWeight)l.Appearance!.LineWeight||native.IsPlottable!=l.Appearance.Plottable)throw new System.Exception("Layer differs: "+l.Name);}tx.Commit();});
 JsonUtil.Atomic(Path.Combine(root,"drafting-native-results.json"),new{passed=cases.Count-failed,total=cases.Count,failed,cases});}
}
